import json
from pathlib import Path
p=Path(__file__).parent;r=json.loads((p/'reviews.json').read_text())
def add(s,v,t,tags,reason,statement=None,solution=None):
 id='hrv_2019_'+s;d=json.loads((p/(id+'.json')).read_text());u='https://mathnet.mit.edu/explorer.html?p='+id
 section=d.get('section');number=d['problem_number'];comp=d['competition']
 if 'Final round' in (section or ''):
  g,num=number.split('.');section='National Competition — Category A, Year '+g;number=num;comp='Croatian National Mathematical Competition'
 else:number='Booklet '+number
 r[id]={'difficulty':v,'topic':t,'tags':tags,'reason':reason,'competition':comp,'section':section,'number':number,'solution':solution or '[Worked solution in the Croatian Mathematical Society booklet, via MathNet]('+u+').','solutionKind':'original-exposition' if solution else 'source-link','sourceUrl':u,'solutionUrl':u,'sourceName':'Croatian Mathematical Society — 2019 English booklet, via MathNet','notes':'The olympiad booklet uses topic labels A, C, G and N; these are retained explicitly as booklet labels.' if number.startswith('Booklet') else ''}
 if statement:r[id]['statement']=statement
add('0a3e3c',4.5,'Algebra',['complex roots','conjugation'],'Conjugate roots force unit modulus and a short roots-of-unity classification.',r'For which $a\in\mathbb C$ does $\prod_{j=1}^4(x-a^j)$ have only real coefficients?')
